import Foundation

/// Maps database media paths to the files bundled in the app - the native twin of
/// the React Native registry in src/components/images.ts.
///
/// Generated by scripts/sync-content.mjs; keys are normalized exactly like the React
/// Native helpers (query string removed, backslashes converted, extension lower-cased)
/// and values are the bundled file names, which are unique across the media set.
enum MediaRegistry {
    static let images: [String: String] = [
// __IMAGES__
    ]

    static let videos: [String: String] = [
// __VIDEOS__
    ]

    /// Normalizes a database media path the same way the React Native app does.
    static func normalizedPath(_ src: String) -> String {
        var value = src
        if let queryIndex = value.firstIndex(of: "?") {
            value = String(value[value.startIndex..<queryIndex])
        }
        value = value.replacingOccurrences(of: "\\", with: "/")
        if let decoded = value.removingPercentEncoding {
            value = decoded
        }
        guard let dot = value.lastIndex(of: "."), let slash = value.lastIndex(of: "/"),
              value.distance(from: value.startIndex, to: dot) > value.distance(from: value.startIndex, to: slash)
        else { return value }
        return String(value[value.startIndex..<dot]) + value[dot...].lowercased()
    }

    static func imageFile(for src: String) -> String? {
        images[normalizedPath(src)]
    }

    static func videoFile(for src: String) -> String? {
        videos[normalizedPath(src)]
    }
}
